// Isolated rung1 kernel. Budget one u32 per parse row in RAM in separate phases,
// never a corpus-sized SA. Refuse beyond explicit width / comparison bounds.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <vector>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
using namespace std;namespace fs=std::filesystem;using U=uint32_t;using Q=uint64_t;
struct Pair{U a,b;};struct Triple{U r,i,j;};U get(istream&f){U x;assert(f.read((char*)&x,4));return x;}
Q reads(){ifstream f("/proc/self/io");string k;Q v;while(f>>k>>v)if(k=="read_bytes:")return v;abort();}
int main(int ac,char**av){assert(ac==6);fs::path corpus=av[1],parse=av[2],inv=av[3],adj=av[4],d=av[5];assert(fs::create_directory(d));Q n=fs::file_size(corpus);assert(n&&n<=1010000000);U m=fs::file_size(parse)/4,k=fs::file_size(adj)/4;assert(m<=32000000 && k<=26000000 && m>0&&k>0&&fs::file_size(inv)==4ull*m); // retained: dict refs, adj, parse, inverse, occurrence CSR (4(k+1)+9m)
 Q live=16ull*k+17ull*m+4,peak=live,comparisons=0;auto add=[&](Q a){live+=a;assert(live<=2*n);peak=max(live,peak);};auto del=[&](fs::path p){live-=fs::file_size(p);assert(fs::remove(p));};auto guard=[&]{assert(reads()<=6*n);};const U S=1<<18,nb=(m+S-1)/S;auto path=[&](U b){return d/("rank"+to_string(b));};
 {vector<ofstream>o(nb);for(U b=0;b<nb;b++)o[b].open(path(b),ios::binary);ifstream f(inv,ios::binary);for(U j=0;j<m;j++){U rank=get(f);assert(rank&&rank<=m);Pair q{rank-1,j};add(8);o[q.a/S].write((char*)&q,8);assert(o[q.a/S]);}for(auto&f:o){f.close();assert(f);}}
 U longpairs=0,maxz=0;{ifstream f(parse,ios::binary);vector<U>pa(m);assert(f.read((char*)pa.data(),4ull*m));ofstream qs(d/"mismatch",ios::binary),sp(d/"sparse",ios::binary);U prev=0;for(U b=0;b<nb;b++){guard();U len=min(S,m-b*S);vector<U>ord(len,UINT32_MAX);ifstream fi(path(b),ios::binary);for(U q=0;q<len;q++){Pair p;assert(fi.read((char*)&p,8)&&p.a/S==b&&p.a%S<len&&ord[p.a%S]==UINT32_MAX&&p.b<m);ord[p.a%S]=p.b;}fi.close();del(path(b));for(U q=0;q<len;q++){U r=b*S+q,j=ord[q],z=0;Pair ids{};if(r){while(prev+z<m&&j+z<m&&pa[prev+z]==pa[j+z]){++z;++comparisons;assert(comparisons<=128ull*m);}assert(prev+z<m&&j+z<m);ids={pa[prev+z],pa[j+z]};assert(ids.a<ids.b&&ids.b<k);if(z){Triple t{r,prev,prev+z};add(12);sp.write((char*)&t,12);++longpairs;maxz=max(maxz,z);}}add(8);qs.write((char*)&ids,8);prev=j;}}qs.close();sp.close();assert(qs&&sp);}
 // Obtain text starts only while resolving the sparse shared-stride queries.
 {int fd=open(corpus.c_str(),O_RDONLY);assert(fd>=0);auto t=(const unsigned char*)mmap(nullptr,n,PROT_READ,MAP_PRIVATE,fd,0);assert(t!=MAP_FAILED);madvise((void*)t,n,MADV_SEQUENTIAL);vector<U>s;s.reserve(m);s.push_back(0);for(U i=1;i+8<=n;i++){if(i%1048576==0)guard();Q h=1469598103934665603ull;for(U x=i;x<i+8;x++)h=(h^t[x])*1099511628211ull;if(h%31==0){assert(s.size()<m);s.push_back(i);}}assert(s.size()==m);munmap((void*)t,n);close(fd);ifstream f(d/"sparse",ios::binary);ofstream o(d/"delta",ios::binary);for(U q=0;q<longpairs;q++){Triple a;assert(f.read((char*)&a,12));Pair p{a.r,s.at(a.j)-s.at(a.i)};add(8);o.write((char*)&p,8);}o.close();assert(o);f.close();del(d/"sparse");}
 {vector<U>v(k);ifstream f(adj,ios::binary);assert(f.read((char*)v.data(),4ull*k));const U B=16,blocks=(k+B-1)/B;vector<U>tree(2*blocks,UINT32_MAX);for(U i=0;i<k;i++)tree[blocks+i/B]=min(tree[blocks+i/B],v[i]);for(U i=blocks-1;i;i--)tree[i]=min(tree[i*2],tree[i*2+1]);auto rmq=[&](U a,U b){U l=a+1,r=b+1,h=UINT32_MAX;while(l<r&&l%B)h=min(h,v[l++]);while(l<r&&r%B)h=min(h,v[--r]);if(l<r){l=l/B+blocks;r=r/B+blocks;while(l<r){if(l&1)h=min(h,tree[l++]);if(r&1)h=min(h,tree[--r]);l/=2;r/=2;}}assert(h!=UINT32_MAX);return h;};ifstream qs(d/"mismatch",ios::binary),sp(d/"delta",ios::binary);ofstream o(d/"aligned.u32",ios::binary);Pair p{UINT32_MAX,0};if(longpairs)assert(sp.read((char*)&p,8));U used=0;for(U r=0;r<m;r++){if(r%262144==0)guard();Pair ids;assert(qs.read((char*)&ids,8));U h=r?rmq(ids.a,ids.b):0;if(p.a==r){h+=p.b;if(++used<longpairs)assert(sp.read((char*)&p,8));}assert(h<=n);add(4);o.write((char*)&h,4);}assert(used==longpairs);o.close();assert(o);qs.close();sp.close();del(d/"mismatch");del(d/"delta");}
 if(n<=101000000){int fd=open(corpus.c_str(),O_RDONLY);assert(fd>=0);auto t=(const unsigned char*)mmap(nullptr,n,PROT_READ,MAP_PRIVATE,fd,0);assert(t!=MAP_FAILED);ifstream ir(inv,ios::binary),al(d/"aligned.u32",ios::binary);vector<U>pos(m,UINT32_MAX);auto insert=[&](U i){U r=get(ir);assert(r>0&&r<=m&&pos[r-1]==UINT32_MAX);pos[r-1]=i;};insert(0);for(U i=1;i+8<=n;i++){Q v=1469598103934665603ull;for(U j=i;j<i+8;j++)v=(v^t[j])*1099511628211ull;if(v%31==0)insert(i);}U prev=0;for(U r=0;r<m;r++){if(r%32768==0)guard();U j=pos[r],h=0;assert(j<n);if(r){while(prev+h<n&&j+h<n&&t[prev+h]==t[j+h])++h;assert(prev+h==n||(j+h<n&&t[prev+h]<t[j+h]));}assert(h==get(al));prev=j;}munmap((void*)t,n);close(fd);}
 guard();printf("ALIGNED rows=%u shared_phrase_pairs=%u max_equal_phrases=%u equal_phrase_comparisons=%llu peak_counted=%llu final_columns=%llu reads=%llu\n",m,longpairs,maxz,(unsigned long long)comparisons,(unsigned long long)peak,(unsigned long long)live,(unsigned long long)reads());}
